import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.Cr9EE2ob.js";const m=JSON.parse('{"title":"End-to-end smoke test","description":"End-to-end smoke test for a live yarilo instance — authenticate, deliver over LMTP, read over IMAP and POP3: how to run it, what it checks, reading failures.","frontmatter":{"description":"End-to-end smoke test for a live yarilo instance — authenticate, deliver over LMTP, read over IMAP and POP3: how to run it, what it checks, reading failures.","head":[["meta",{"name":"robots","content":"noindex"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/main/operations/smoke.html"}],["meta",{"property":"og:title","content":"End-to-end smoke test"}],["meta",{"name":"twitter:title","content":"End-to-end smoke test"}],["meta",{"property":"og:description","content":"End-to-end smoke test for a live yarilo instance — authenticate, deliver over LMTP, read over IMAP and POP3: how to run it, what it checks, reading failures."}],["meta",{"name":"twitter:description","content":"End-to-end smoke test for a live yarilo instance — authenticate, deliver over LMTP, read over IMAP and POP3: how to run it, what it checks, reading failures."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/main/operations/smoke.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/main/operations/smoke.html\\",\\"headline\\":\\"End-to-end smoke test\\",\\"description\\":\\"End-to-end smoke test for a live yarilo instance — authenticate, deliver over LMTP, read over IMAP and POP3: how to run it, what it checks, reading failures.\\",\\"dateModified\\":\\"2026-10-22T19:47:38.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/main/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"End-to-end smoke test\\",\\"item\\":\\"https://doc.yarilomail.org/main/operations/smoke.html\\"}]}]}"]]},"headers":[],"relativePath":"operations/smoke.md","filePath":"operations/smoke.md","lastUpdated":1792698458000}'),n={name:"operations/smoke.md"};function o(r,e,l,d,h,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="end-to-end-smoke-test" tabindex="-1">End-to-end smoke test <a class="header-anchor" href="#end-to-end-smoke-test" aria-label="Permalink to &quot;End-to-end smoke test&quot;">​</a></h1><p>Drives a live yarilo instance through the full happy-path mail flow: authenticate → deliver → read.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Step</th><th style="text-align:left;">What it exercises</th></tr></thead><tbody><tr><td style="text-align:left;">Submission AUTH PLAIN over STARTTLS</td><td style="text-align:left;">passdb chain, bcrypt verify, STARTTLS handshake</td></tr><tr><td style="text-align:left;">Submission AUTH LOGIN over STARTTLS</td><td style="text-align:left;">legacy SASL LOGIN mechanism (Outlook, Android MUAs)</td></tr><tr><td style="text-align:left;">LMTP delivery</td><td style="text-align:left;">storage write path, auto-provisioning of new mailboxes</td></tr><tr><td style="text-align:left;">IMAPS LOGIN command</td><td style="text-align:left;">IMAP native <code>LOGIN user password</code> (RFC 3501)</td></tr><tr><td style="text-align:left;">IMAPS AUTHENTICATE PLAIN</td><td style="text-align:left;">IMAP SASL PLAIN via AUTHENTICATE</td></tr><tr><td style="text-align:left;">POP3S USER/PASS</td><td style="text-align:left;">POP3 native <code>USER</code> + <code>PASS</code></td></tr><tr><td style="text-align:left;">POP3S AUTH PLAIN (SASL)</td><td style="text-align:left;">POP3 SASL PLAIN via AUTH (RFC 5034), with initial response</td></tr></tbody></table><p>The harness lives in <a href="https://github.com/yarilomail/yarilo/tree/main/app/smoketest-e2e" target="_blank" rel="noreferrer"><code>app/<wbr>smoketest-e2e</code></a> and runs against any yarilo deployment exposing the listeners — local binary, docker compose, or staging cluster.</p><hr><h2 id="running-it" tabindex="-1">Running it <a class="header-anchor" href="#running-it" aria-label="Permalink to &quot;Running it&quot;">​</a></h2><p>The harness needs a running stack: sessions authenticate through <code>yarilo-auth</code>, so a single server process cannot stand in for one. Locally, that is the <a href="/main/installation/docker_compose.html">Docker Compose</a> stack, with a user created as described in <a href="/main/installation/docker_compose.html#creating-the-first-user">Creating the first user</a>. The binary is not in the image; run it from a checkout:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./app/smoketest-e2e</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user@example.test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pass</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changeit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -submission-port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 587</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lmtp-port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -imaps-port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 993</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pop3s-port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 995</span></span></code></pre></div><p>LMTP on 24 is published on the loopback interface only, so run it on the Docker host. Each step prints <code>[PASS]</code> or <code>[FAIL]</code> with its name, in the order of the table above.</p><p>The compose stack&#39;s certificate is self-signed, and <code>-insecure</code> defaults to <code>true</code>, so the command above does not verify it. Against a deployment with a real certificate, pass <code>-insecure=false</code>: leaving the flag out does <strong>not</strong> turn verification on.</p><p><code>app/<wbr>smoketest-e2e/<wbr>seed</code> writes a bcrypt user into a SQLite userdb file, for a stack whose <code>yarilo-auth</code> reads one you can reach from the host.</p><hr><h2 id="cli-flags" tabindex="-1">CLI flags <a class="header-anchor" href="#cli-flags" aria-label="Permalink to &quot;CLI flags&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-host          target hostname           (default: 127.0.0.1)</span></span>
<span class="line"><span>-user          mailbox login             (default: alice@smoke.local)</span></span>
<span class="line"><span>-pass          password                  (default: wonderland)</span></span>
<span class="line"><span>-submission-port  STARTTLS submission    (default: 9587)</span></span>
<span class="line"><span>-lmtp-port        plain TCP LMTP         (default: 9024)</span></span>
<span class="line"><span>-imaps-port       IMAPS                  (default: 9993)</span></span>
<span class="line"><span>-pop3s-port       POP3S                  (default: 9995)</span></span>
<span class="line"><span>-insecure         skip TLS verify         (default: true — pass -insecure=false to verify)</span></span>
<span class="line"><span>-timeout          per-step timeout        (default: 10s)</span></span></code></pre></div><p>Against a real deployment, point <code>-host</code> at the public hostname, use the standard ports <code>587 /<wbr> 24 /<wbr> 993 /<wbr> 995</code>, and pass <code>-insecure=false</code>.</p><hr><h2 id="what-auto-provisioning-means" tabindex="-1">What auto-provisioning means <a class="header-anchor" href="#what-auto-provisioning-means" aria-label="Permalink to &quot;What auto-provisioning means&quot;">​</a></h2><p>When LMTP receives a message for a user whose Maildir doesn&#39;t exist, it creates <code>INBOX/<wbr>{cur,new,tmp}/</code> and proceeds. This matches the reference&#39;s behavior — LMTP is internal, the upstream MTA has already vetted recipients.</p><p>If you want strict recipient validation at the LMTP layer (instead of trusting the MTA), file an issue — there&#39;s currently no <code>lmtp_<wbr>reject_<wbr>unknown_<wbr>recipients</code> knob.</p><hr><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Code</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;">0</td><td style="text-align:left;">All seven steps passed.</td></tr><tr><td style="text-align:left;">1</td><td style="text-align:left;">One or more steps failed (details on stderr).</td></tr></tbody></table><h2 id="the-per-rollout-gate-app-smoketest" tabindex="-1">The per-rollout gate (<code>app/<wbr>smoketest</code>) <a class="header-anchor" href="#the-per-rollout-gate-app-smoketest" aria-label="Permalink to &quot;The per-rollout gate (\`app/smoketest\`)&quot;">​</a></h2><p>The two sections below describe <code>app/<wbr>smoketest</code>, the per-rollout gate covered in <a href="/main/operations/testing.html">Testing</a>, not the end-to-end harness above.</p><h3 id="jmap-header-forms-and-property-validation" tabindex="-1">JMAP header forms and property validation <a class="header-anchor" href="#jmap-header-forms-and-property-validation" aria-label="Permalink to &quot;JMAP header forms and property validation&quot;">​</a></h3><p>The last JMAP check is the only one that <strong>writes</strong>. It appends its own message to a folder of its own, <code>YariloSmoke</code>, reads it back through every <code>header:*</code> form of RFC 8621 §4.1.3, and removes both afterwards.</p><p>It brings its own message because the alternative is depending on whatever happens to be in the mailbox — which differs per deployment, so a green run would mean different things in different places.</p><p><strong>The folder rather than INBOX</strong> because the check runs on every rollout, and a message left behind changes the mailbox every other measurement is taken against. Cleanup is best effort and <strong>reported when it fails</strong>: leaving the folder is recoverable, not knowing it was left is not.</p><p>It needs <code>-jmap-user</code> and <code>-jmap-pass</code>, and it is skipped without them.</p><p>What it asserts beyond the forms themselves:</p><ul><li>the response carries <strong>only</strong> the requested properties — an unprojected answer states <code>hasAttachment: false</code> for a message that has one;</li><li>a missing header is answered <code>null</code> and is <strong>present</strong> in the object, checked separately from its value because in Go a missing key and a null value are both <code>nil</code>;</li><li>a misspelled property is refused with <code>invalidArguments</code> — silence there is indistinguishable from a property yarilo has not implemented;</li><li><code>headers</code> lists every field in the order the message carries them.</li></ul><h3 id="what-the-gate-writes-and-what-it-removes" tabindex="-1">What the gate writes, and what it removes <a class="header-anchor" href="#what-the-gate-writes-and-what-it-removes" aria-label="Permalink to &quot;What the gate writes, and what it removes&quot;">​</a></h3><p>It writes. Run it against an account whose mail you are willing to have touched in the ways below, and nothing else.</p><table tabindex="0"><thead><tr><th style="text-align:left;">check</th><th style="text-align:left;">writes</th><th style="text-align:left;">removes</th></tr></thead><tbody><tr><td style="text-align:left;">sieve checks</td><td style="text-align:left;">one message per check, delivered by LMTP</td><td style="text-align:left;">its own message, by the unique subject it sent</td></tr><tr><td style="text-align:left;">sieve <code>fileinto</code> and friends</td><td style="text-align:left;">messages into folders they create</td><td style="text-align:left;">those folders&#39; contents</td></tr><tr><td style="text-align:left;">FTS</td><td style="text-align:left;">one message with a unique marker</td><td style="text-align:left;">nothing</td></tr><tr><td style="text-align:left;">JMAP header forms</td><td style="text-align:left;">one message in <code>YariloSmoke</code></td><td style="text-align:left;">that message and the folder</td></tr></tbody></table><p><strong>It does not empty INBOX</strong>, and must not: the account need not be disposable. Every check identifies its own message by a unique subject or marker. <code>TestNothingEmptiesTheInbox</code> reads the source and fails on any function that selects INBOX, searches <code>ALL</code> and deletes the result — deleting a message the check itself sent stays allowed, because the fault was the breadth and not the delete.</p>`,35)])])}const g=t(n,[["render",o]]);export{m as __pageData,g as default};
